def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # Maps key to (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries first
            keys_to_remove = []
            for k, (v, write_time) in cache.items():
                if t >= write_time + ttl:
                    keys_to_remove.append(k)
            for k in keys_to_remove:
                del cache[k]

            # If key exists, remove it to re-insert at end
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Insert/update the key
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries first
            keys_to_remove = []
            for k, (v, write_time) in cache.items():
                if t >= write_time + ttl:
                    keys_to_remove.append(k)
            for k in keys_to_remove:
                del cache[k]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

